package updateobject

import (
	"fmt"

	"github.com/Ltz-lab/wow-live/protocol/codec"
)

// Delta (values-update) layouts. A struct's delta starts with its change
// mask, MSB-first in one bit stream: a word of block-present bits (one per
// 32-bit block) and then each present block (bit i of block k is mask bit
// 32k+i). ObjectData and GameObjectData are the exception: a plain mask of 4
// and 28 bits. Values follow,
// byte aligned, in the order the client reads them (delta_tables.go,
// generated by tools/ufdelta.py from the client's delta readers).
//
// A child bit counts only when its group bit is set too: the client tests
// the group first. Any effective bit the tables mark unsupported, or do not
// know, makes the whole delta ErrUnsupported: without it the position of
// every later value is unknown.

type deltaGroup struct{ bit, last int }

type deltaField struct {
	bit     int
	name    string
	width   Width
	trailer bool // a bit-group byte read when group bit is set
	// read, when set, reads a nested part (a sub-struct with its own change
	// mask, a map, a list) at this point of the client's read order, when
	// the bit is effective. name and width are unused (delta_nested.go).
	read func(d *rd, m mask, out *fieldSet)
}

type deltaLayout struct {
	name        string
	blocks      int // 0: a plain mask of plainBits bits
	plainBits   int
	groups      []deltaGroup
	prelude     int // bit-group bytes before the first value
	fields      []deltaField
	unsupported map[int]string
	// prelude reads the struct's bits between the mask and the first value
	// (UnitData, PlayerData); nil when there are none.
	preludeFn func(d *rd, m mask, out *fieldSet)
}

// mask is a decoded change mask.
type mask []uint32

func (m mask) has(bit int) bool {
	k := bit / 32
	return k < len(m) && m[k]&(1<<uint(bit%32)) != 0
}

func (l *deltaLayout) groupOf(bit int) (int, bool) {
	for _, g := range l.groups {
		if g.bit < bit && bit <= g.last {
			return g.bit, true
		}
	}
	return 0, false
}

func (l *deltaLayout) effective(m mask, bit int) bool {
	if !m.has(bit) {
		return false
	}
	if g, ok := l.groupOf(bit); ok {
		return m.has(g)
	}
	return true
}

func (l *deltaLayout) isGroup(bit int) bool {
	for _, g := range l.groups {
		if g.bit == bit {
			return true
		}
	}
	return false
}

func (d *rd) readMask(l *deltaLayout) mask {
	if l.blocks == 0 {
		return mask{uint32(d.bitsTraced0(uint(l.plainBits)))}
	}
	present := d.bitsTraced0(uint(l.blocks))
	m := make(mask, l.blocks)
	for k := 0; k < l.blocks; k++ {
		if present&(1<<uint(k)) != 0 {
			m[k] = uint32(d.bitsTraced(32))
		}
	}
	return m
}

// bitsTraced0 starts a bit group and reads n bits.
func (d *rd) bitsTraced0(n uint) uint64 {
	d.group()
	return d.bitsTraced(n)
}

// readDelta decodes one struct's delta. prelude handles the struct's bit
// group before the first value (UnitData); it is nil when there is none.
func (d *rd) readDelta(l *deltaLayout, prelude func(*rd, mask, *fieldSet)) []Field {
	m := d.readMask(l)
	if d.err != nil {
		return nil
	}
	known := map[int]bool{}
	for _, f := range l.fields {
		if !f.trailer {
			known[f.bit] = true
		}
	}
	if prelude == nil {
		prelude = l.preludeFn
	}
	d.fullNested = false
	for k, w := range m {
		for i := 0; i < 32; i++ {
			bit := 32*k + i
			if w&(1<<uint(i)) == 0 || l.isGroup(bit) || !l.effective(m, bit) {
				continue
			}
			if why, ok := l.unsupported[bit]; ok {
				d.fail(fmt.Errorf("%w: %s delta bit %d (%s)", ErrUnsupported, l.name, bit, why))
				return nil
			}
			if !known[bit] && (prelude == nil || !preludeBits[l.name][bit]) {
				d.fail(fmt.Errorf("%w: %s delta bit %d is not in the client's layout", ErrUnsupported, l.name, bit))
				return nil
			}
		}
	}
	var out fieldSet
	if prelude != nil {
		prelude(d, m, &out)
	} else if l.prelude != 0 {
		d.fail(fmt.Errorf("updateobject: %s has a prelude but no handler", l.name))
	}
	d.inBits = false
	for _, f := range l.fields {
		if d.err != nil {
			return nil
		}
		if f.read != nil {
			if l.effective(m, f.bit) {
				f.read(d, m, &out)
			}
			continue
		}
		if f.trailer {
			if m.has(f.bit) {
				d.group()
				d.traceRead("1", 0)
				if b := d.bits(8); b != 0 {
					d.fail(fmt.Errorf("%w: %s bit group after group %d is %#02x", ErrUnsupported, l.name, f.bit, b))
				}
			}
			continue
		}
		if l.effective(m, f.bit) {
			d.traceRead(getterOf(f.width), 0)
			out.add(Field{Name: f.name, Width: f.width, Value: d.value(f.width)})
		}
	}
	return out.list
}

// preludeBits are bits read inside a struct's prelude.
var preludeBits = map[string]map[int]bool{
	"UnitData":       {1: true, 2: true, 3: true, 4: true, 5: true},
	"PlayerData":     {1: true, 2: true},
	"GameObjectData": {1: true, 2: true, 3: true},
	"ItemData":       {1: true, 2: true},
}

// deltaBit is one changed bit, for writeDelta.
type deltaValues map[string]any

// writeDelta encodes a delta that sets exactly the given fields (by name)
// and their group bits. It exists for fixtures.
func writeDelta(w *codec.Writer, l *deltaLayout, vals deltaValues) error {
	byName := map[string]deltaField{}
	for _, f := range l.fields {
		if !f.trailer && f.read == nil {
			byName[f.name] = f
		}
	}
	nblocks := l.blocks
	if nblocks == 0 {
		nblocks = 1
	}
	m := make(mask, nblocks)
	set := func(bit int) { m[bit/32] |= 1 << uint(bit%32) }
	for name := range vals {
		if name == "Field_314" && l == &unitDataDelta {
			set(1)
			set(0)
			continue
		}
		f, ok := byName[name]
		if !ok {
			return fmt.Errorf("updateobject: %s has no delta field %q", l.name, name)
		}
		set(f.bit)
		if g, ok := l.groupOf(f.bit); ok {
			set(g)
		}
	}
	w.FlushBits()
	if l.blocks == 0 {
		if err := w.Bits(uint64(m[0]), uint(l.plainBits)); err != nil {
			return err
		}
	} else {
		var present uint64
		for k := range m {
			if m[k] != 0 {
				present |= 1 << uint(k)
			}
		}
		if err := w.Bits(present, uint(l.blocks)); err != nil {
			return err
		}
		for k := range m {
			if m[k] != 0 {
				if err := w.Bits(uint64(m[k]), 32); err != nil {
					return err
				}
			}
		}
	}
	if l == &unitDataDelta {
		w.FlushBits()
		w.Bit(false)
		if v, ok := vals["Field_314"]; ok {
			b, _ := v.(bool)
			w.Bit(b)
		}
	}
	for _, f := range l.fields {
		if f.read != nil && !f.trailer {
			continue
		}
		if f.trailer {
			if m.has(f.bit) {
				w.FlushBits()
				w.Uint8(0)
			}
			continue
		}
		if l.effective(m, f.bit) {
			if err := writeValue(w, f.width, vals[f.name]); err != nil {
				return fmt.Errorf("%s: %w", f.name, err)
			}
		}
	}
	return nil
}
